// ===== PRODUCT PAGE =====
// Each product has its own page: products/<key>.html (generated by tools/build.mjs).
// The page body carries data-key="<key>"; old links like product.html#<key> are redirected there.
const all=[];Object.entries(sets).forEach(([cat,list])=>list.forEach(p=>all.push({...p,cat})));

function cardHTML(p){
  return '<a class="card" href="'+productUrl(p.key)+'"><div class="img">'+
    '<img class="'+(p.back?'front ':'')+'contain" src="'+P+p.front+'.webp" alt="'+esc(p.name)+'" loading="lazy" decoding="async">'+
    (p.back?'<img class="back contain" src="'+P+p.back+'.webp" alt="" loading="lazy" decoding="async">':'')+
    '</div><h3>'+esc(p.name)+'</h3><p class="sub">'+catLabel[p.cat]+'</p></a>';
}
function notFound(){
  document.title='Piece not found · Pieces Collective';
  document.getElementById('pd').innerHTML='<div class="nf"><span class="kick">404</span><h1>Piece not found</h1>'+
    '<p>This piece doesn\'t exist or is no longer available.</p><a class="pill2" href="'+ROOT+'shop.html">Back to the shop ›</a></div>';
  const m=document.querySelector('.more');if(m)m.style.display='none';
}
function render(){
  const key=document.body.dataset.key||location.hash.slice(1);
  const pr=all.find(p=>p.key===key);
  if(!pr){notFound();return;}
  if(!document.body.dataset.key){location.replace(productUrl(pr.key));return;} // old product.html#key link
  document.title=pr.name+' – '+catLabel[pr.cat]+' · Pieces Collective';
  const imgs=[pr.front].concat(pr.back?[pr.back]:[]);
  const ch=sizeChart[pr.cat],SIZES=ch.sizes;
  const want=decodeURIComponent((location.hash.match(/^#size-(\w+)$/)||[])[1]||'');
  let size=SIZES.includes(want)?want:(SIZES.includes('M')?'M':SIZES[0]);
  document.getElementById('pd').innerHTML=
   '<a class="back" href="'+ROOT+'shop.html">‹ Back to all pieces</a>'+
   '<div class="gal"><div class="main" id="mainImg" style="background:radial-gradient(circle at 50% 42%,'+pr.c[0]+'55,#101010 72%)">'+
     imgs.map((s,i)=>'<img src="'+P+s+'.webp" alt="'+esc(pr.name)+(i?' – back':' – front')+'" width="800" height="800" style="opacity:'+(i?0:1)+'"'+(i?' loading="lazy"':' fetchpriority="high"')+'>').join('')+'</div>'+
     (imgs.length>1?'<div class="thumbs">'+imgs.map((s,i)=>'<button type="button" class="'+(i?'':'on')+'" data-i="'+i+'" aria-label="Show '+(i?'back':'front')+'" aria-pressed="'+(i?'false':'true')+'"><img src="'+P+s+'.webp" alt="" loading="lazy"></button>').join('')+'</div>':'')+
   '</div>'+
   '<div class="info"><div class="cat">'+catLabel[pr.cat]+'</div><h1>'+esc(pr.name)+'</h1><div class="fit">'+fitInfo[pr.cat]+'</div>'+
     '<p class="desc">'+esc(pr.desc)+'</p>'+
     '<div class="lbl" id="sizeLbl">Choose your size:</div><div class="psizes" id="psizes" role="group" aria-labelledby="sizeLbl">'+
       SIZES.map(s=>'<button type="button" class="'+(s===size?'on':'')+'" aria-pressed="'+(s===size)+'">'+s+'</button>').join('')+'</div>'+
     '<div class="inq" id="inq"></div><p class="note">Message us to order or check availability.</p>'+
     '<div class="chart"><h2 class="h3">Size chart (inches)</h2><table><tr><th scope="col"><span class="sr-only">Measurement</span></th>'+SIZES.map(s=>'<th scope="col">'+s+'</th>').join('')+'</tr>'+
       ch.rows.map((r,ri)=>'<tr><th scope="row">'+r+'</th>'+SIZES.map(s=>'<td>'+ch[s][ri]+'</td>').join('')+'</tr>').join('')+'</table></div>'+
   '</div>';
  const setInq=()=>document.getElementById('inq').innerHTML=inqButtons(pr.name,size);setInq();
  document.querySelectorAll('#psizes button').forEach(b=>b.onclick=()=>{size=b.textContent;
    document.querySelectorAll('#psizes button').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',x===b);});setInq();});
  document.querySelectorAll('.thumbs button').forEach(b=>b.onclick=()=>{const i=+b.dataset.i;
    document.querySelectorAll('#mainImg img').forEach((im,n)=>im.style.opacity=n===i?1:0);
    document.querySelectorAll('.thumbs button').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',x===b);});});
  // you may also like: same category first, then others
  const others=all.filter(p=>p.key!==pr.key);
  const pick=others.filter(p=>p.cat===pr.cat).concat(others.filter(p=>p.cat!==pr.cat)).slice(0,4);
  document.getElementById('moreGrid').innerHTML=pick.map(cardHTML).join('');
}
render();
